 13→const (
 14→	maxResponseBytes = 1 << 20
 15→	userAgent        = "entire-cli"
 16→)
 17→
 18→// Client is an authenticated HTTP client for the Entire API.
 19→// It attaches the bearer token to all outgoing requests via the Authorization header.
 20→type Client struct {
 21→	httpClient *http.Client
 22→	baseURL    string
 23→}
 24→
 25→// NewClient creates a new authenticated API client with an explicit bearer token.
 26→func NewClient(token string) *Client {
 27→	return &Client{
 28→		httpClient: &http.Client{
 29→			Transport: &bearerTransport{
 30→				token: token,
 31→				base:  http.DefaultTransport,
 32→			},
 33→		},
 34→		baseURL: BaseURL(),
 35→	}
 36→}
 37→
 38→// bearerTransport is an http.RoundTripper that injects the Authorization header.
 39→type bearerTransport struct {
 40→	token string
 41→	base  http.RoundTripper
 42→}
 43→
 44→func (t *bearerTransport) RoundTrip(req *http.Request) (*http.Response, error) {
 45→	// Clone the request to avoid mutating the caller's request.
 46→	r := req.Clone(req.Context())
 47→	r.Header.Set("Authorization", "Bearer "+t.token)
 48→	r.Header.Set("User-Agent", userAgent)
 49→	if r.Header.Get("Accept") == "" {
 50→		r.Header.Set("Accept", "application/json")
 51→	}
 52→	resp, err := t.base.RoundTrip(r)
 53→	if err != nil {
 54→		return nil, fmt.Errorf("round trip: %w", err)
 55→	}
 56→	return resp, nil
 57→}
 58→
 59→// Get sends an authenticated GET request to the given API-relative path.
 60→func (c *Client) Get(ctx context.Context, path string) (*http.Response, error) {
 61→	return c.do(ctx, http.MethodGet, path, nil)
 62→}
 63→
 64→// Post sends an authenticated POST request with a JSON body to the given API-relative path.
 65→func (c *Client) Post(ctx context.Context, path string, body any) (*http.Response, error) {
 66→	var reader io.Reader
 67→	if body != nil {
 68→		data, err := json.Marshal(body)
 69→		if err != nil {
 70→			return nil, fmt.Errorf("marshal request body: %w", err)
 71→		}
 72→		reader = bytes.NewReader(data)
 73→	}
 74→	return c.do(ctx, http.MethodPost, path, reader)
 75→}
 76→
 77→// Put sends an authenticated PUT request with a JSON body to the given API-relative path.
 78→func (c *Client) Put(ctx context.Context, path string, body any) (*http.Response, error) {
 79→	var reader io.Reader
 80→	if body != nil {
 81→		data, err := json.Marshal(body)
 82→		if err != nil {
 83→			return nil, fmt.Errorf("marshal request body: %w", err)
 84→		}
 85→		reader = bytes.NewReader(data)
 86→	}
 87→	return c.do(ctx, http.MethodPut, path, reader)
 88→}
 89→
 90→// Delete sends an authenticated DELETE request to the given API-relative path.
 91→func (c *Client) Delete(ctx context.Context, path string) (*http.Response, error) {
 92→	return c.do(ctx, http.MethodDelete, path, nil)
 93→}
 94→
 95→func (c *Client) do(ctx context.Context, method, path string, body io.Reader) (*http.Response, error) {
 96→	endpoint, err := ResolveURLFromBase(c.baseURL, path)
 97→	if err != nil {
 98→		return nil, fmt.Errorf("resolve URL %s: %w", path, err)
 99→	}
100→
101→	req, err := http.NewRequestWithContext(ctx, method, endpoint, body)
102→	if err != nil {
103→		return nil, fmt.Errorf("create request: %w", err)
104→	}
105→
106→	if body != nil {
107→		req.Header.Set("Content-Type", "application/json")
108→	}
109→
110→	resp, err := c.httpClient.Do(req)
111→	if err != nil {
112→		return nil, fmt.Errorf("%s %s: %w", method, path, err)
113→	}
114→	return resp, nil
115→}
116→
117→// DecodeJSON reads the response body and decodes it into dest.
118→// It limits the body size to protect against unbounded reads.
119→func DecodeJSON(resp *http.Response, dest any) error {
120→	defer resp.Body.Close()
121→	body, err := io.ReadAll(io.LimitReader(resp.Body, maxResponseBytes))
122→	if err != nil {
123→		return fmt.Errorf("read response body: %w", err)
124→	}
125→
126→	if err := json.Unmarshal(body, dest); err != nil {
127→		return fmt.Errorf("decode JSON response: %w", err)
128→	}
129→
130→	return nil
131→}
132→
133→// ErrorResponse represents a standard API error response.
134→type ErrorResponse struct {
135→	Error string `json:"error"`
136→}
137→
138→// CheckResponse returns an error if the response status code indicates failure.
139→// For non-2xx responses, it attempts to parse the error message from the body.
140→func CheckResponse(resp *http.Response) error {
141→	if resp.StatusCode >= 200 && resp.StatusCode < 300 {
142→		return nil
143→	}
144→
145→	defer resp.Body.Close()
146→	body, err := io.ReadAll(io.LimitReader(resp.Body, maxResponseBytes))
147→	if err != nil {
148→		return fmt.Errorf("API error: status %d", resp.StatusCode)
149→	}
150→
151→	var apiErr ErrorResponse
152→	if err := json.Unmarshal(body, &apiErr); err == nil && strings.TrimSpace(apiErr.Error) != "" {
153→		return fmt.Errorf("API error: %s (status %d)", apiErr.Error, resp.StatusCode)
154→	}
155→
156→	text := strings.TrimSpace(string(body))
157→	if text != "" {
158→		return fmt.Errorf("API error: %s (status %d)", text, resp.StatusCode)
159→	}
160→
161→	return fmt.Errorf("API error: status %d", resp.StatusCode)
162→}
