627→      const body = await c.req.json<{
628→        branch?: string;
629→        base?: string;
630→        status?: string;
631→        title?: string;
632→        body?: string;
633→        assignees?: string[];
634→        labels?: string[];
635→        priority?: string;
636→        type?: string;
637→      }>();
638→
639→      if (
640→        body.branch === undefined &&
641→        body.base === undefined &&
642→        !body.status &&
643→        body.title === undefined &&
644→        body.body === undefined &&
645→        body.assignees === undefined &&
646→        body.labels === undefined &&
647→        body.priority === undefined &&
648→        body.type === undefined
649→      ) {
650→        return c.json({ error: "At least one field is required" }, 400);
651→      }
652→
653→      if (body.status && !VALID_TRAIL_STATUSES.includes(body.status as TrailStatus)) {
654→        return c.json({ error: `Invalid status. Must be one of: ${VALID_TRAIL_STATUSES.join(", ")}` }, 400);
655→      }
656→
657→      if (body.title !== undefined && !body.title.trim()) {
658→        return c.json({ error: "Title cannot be empty" }, 400);
659→      }
660→
661→      if (body.priority !== undefined && !VALID_PRIORITIES.includes(body.priority as TrailPriority)) {
662→        return c.json({ error: `Invalid priority. Must be one of: ${VALID_PRIORITIES.join(", ")}` }, 400);
663→      }
664→
665→      if (body.type !== undefined && body.type !== null && !VALID_TYPES.includes(body.type as TrailType)) {
666→        return c.json({ error: `Invalid type. Must be one of: ${VALID_TYPES.join(", ")}` }, 400);
667→      }
668→
669→      const row = await db.trails.getByTrailId(repoAccess.id, trailId);
670→      if (!row) {
671→        return c.json({ error: "Trail not found" }, 404);
672→      }
673→
674→      if (body.status && row.status === "merged") {
675→        return c.json({ error: "Cannot change the status of a merged trail" }, 422);
676→      }
677→
678→      const updateData: import("../types/database").RepoTrailUpdate = {
679→        updated_at: new Date().toISOString(),
680→      };
681→
682→      if (body.branch !== undefined) updateData.branch = body.branch;
683→      if (body.base !== undefined) updateData.base = body.base;
684→      if (body.status) updateData.status = body.status as TrailStatus;
685→      if (body.title !== undefined) updateData.title = body.title.trim();
686→      if (body.body !== undefined) updateData.body = body.body ?? "";
687→      if (body.assignees !== undefined) updateData.assignees = body.assignees;
688→      if (body.labels !== undefined) updateData.labels = body.labels;
689→      if (body.priority !== undefined) updateData.priority = body.priority;
690→      if (body.type !== undefined) updateData.type = body.type || null;
691→      if (body.status === "in_review" && row.status !== "in_review") {
692→        const existingReviewers = Array.isArray(row.reviewers) ? row.reviewers : [];
