import { Hono } from "hono"

import type { Env, Variables, AppContext } from "../env"
import { sha256Hex, generateApiToken } from "../lib/crypto"
import { getDb } from "../lib/db"
import { requireAuth, rateLimitAuthenticated, rateLimitUnauthenticated } from "../lib/middleware"
import { nullIfInvalidUuid } from "../lib/uuid"

// Characters excluding ambiguous ones (0/O, 1/I/l).
// Length MUST be a power of 2 so that (byte % length) is uniformly distributed.
const CODE_CHARS = "REDACTED" // 32 chars

function generateUserCode(): string {
  const bytes = crypto.getRandomValues(new Uint8Array(8))
  const chars = Array.from(bytes, (b) => CODE_CHARS[b % CODE_CHARS.length])
  return chars.slice(0, 4).join("") + "-" + chars.slice(4).join("")
}

type DeviceGrantStatus = "pending" | "approved" | "denied" | "consumed"

interface DeviceGrant {
  clientId: string
  userCode: string
  scope: string
  status: DeviceGrantStatus
  expiresAt: number
  interval: number
  lastPolledAt?: number
  approvedByUserId?: string
}

interface DevicePollState {
  interval: number
  lastPolledAt: number
}

const CLI_CLIENT_ID = "entire-cli"
const DEFAULT_SCOPE = "cli"
const API_TOKEN_TTL_DAYS = 30
const API_TOKEN_TTL_SECONDS = API_TOKEN_TTL_DAYS * 24 * 60 * 60
const DEVICE_CODE_TTL_SECONDS = 600
const DEVICE_POLL_INTERVAL_SECONDS = 5

function deviceGrantKey(deviceCode: string): string {
  return `cli_auth:${deviceCode}`
}

function userCodeKey(userCode: string): string {
  return `cli_auth_code:${userCode}`
}

function devicePollStateKey(deviceCode: string): string {
  return `cli_auth_poll:${deviceCode}`
}

function isExpired(grant: DeviceGrant): boolean {
  return Date.now() > grant.expiresAt
}

async function getDeviceGrant(c: { env: Env }, deviceCode: string): Promise<DeviceGrant | null> {
  return c.env.ENTIRE_CACHE.get<DeviceGrant>(deviceGrantKey(deviceCode), "json")
}

async function saveDeviceGrant(
  c: { env: Env },
  deviceCode: string,
  grant: DeviceGrant,
): Promise<void> {
  const ttlSeconds = Math.max(1, Math.ceil((grant.expiresAt - Date.now()) / 1000))
  await c.env.ENTIRE_CACHE.put(deviceGrantKey(deviceCode), JSON.stringify(grant), {
    expirationTtl: ttlSeconds,
  })
}

async function getDevicePollState(
  c: { env: Env },
  deviceCode: string,
): Promise<DevicePollState | null> {
  return c.env.ENTIRE_CACHE.get<DevicePollState>(devicePollStateKey(deviceCode), "json")
}

async function saveDevicePollState(
  c: { env: Env },
  deviceCode: string,
  expiresAt: number,
  pollState: DevicePollState,
): Promise<void> {
  const ttlSeconds = Math.max(1, Math.ceil((expiresAt - Date.now()) / 1000))
  await c.env.ENTIRE_CACHE.put(devicePollStateKey(deviceCode), JSON.stringify(pollState), {
    expirationTtl: ttlSeconds,
  })
}

async function createDeviceGrant(
  c: { env: Env },
  clientId: string,
  scope = DEFAULT_SCOPE,
): Promise<{ deviceCode: string; grant: DeviceGrant }> {
  const deviceCode = crypto.randomUUID()
  const grant: DeviceGrant = {
    clientId,
    userCode: generateUserCode(),
    scope,
    status: "pending",
    expiresAt: Date.now() + DEVICE_CODE_TTL_SECONDS * 1000,
    interval: DEVICE_POLL_INTERVAL_SECONDS,
  }

  await Promise.all([
    saveDeviceGrant(c, deviceCode, grant),
    c.env.ENTIRE_CACHE.put(userCodeKey(grant.userCode), deviceCode, {
      expirationTtl: DEVICE_CODE_TTL_SECONDS,
    }),
  ])

  return { deviceCode, grant }
}

async function issueApiToken(c: { env: Env }, userId: string, scope: string): Promise<string> {
  const plainToken = generateApiToken()
  const tokenHash = await sha256Hex(plainToken)
  const now = new Date()
  const expiresAt = new Date(now.getTime() + API_TOKEN_TTL_SECONDS * 1000)
  const db = getDb(c.env)

  await db.apiTokens.create({
    userId,
    tokenHash,
    name: `CLI login ${now.toISOString().split("T")[0]}`,
    scope,
    expiresAt: expiresAt.toISOString(),
  })

  return plainToken
}

function verificationUri(env: Env): string {
  return `${env.FRONTEND_BASE_URL}/cli/auth`
}

function oauthError(c: AppContext, error: string, status: 400 | 401 = 400) {
  return c.json({ error }, status)
}

async function handleDecision(
  c: AppContext,
  userCode: string | undefined,
  decision: "approve" | "deny" | undefined,
): Promise<Response> {
  if (!userCode) {
    return c.json({ error: "Missing userCode" }, 400)
  }
  if (decision !== "approve" && decision !== "deny") {
    return c.json({ error: "Invalid or missing decision" }, 400)
  }

  const deviceCode = await c.env.ENTIRE_CACHE.get(userCodeKey(userCode))
  if (!deviceCode) {
    return c.json({ error: "Invalid or expired code" }, 400)
  }

  const grant = await getDeviceGrant(c, deviceCode)
  if (!grant || isExpired(grant) || grant.status !== "pending") {
    return c.json({ error: "Invalid or expired code" }, 400)
  }

  const userId = c.get("userId")
  if (decision === "deny") {
    grant.status = "denied"
  } else {
    grant.status = "approved"
    grant.approvedByUserId = userId
    // Token is generated at poll-time, not here — avoids storing plaintext in KV
  }

  await saveDeviceGrant(c, deviceCode, grant)
  await c.env.ENTIRE_CACHE.delete(userCodeKey(userCode))
  return c.json({ success: true })
}

export const cliAuthRoutes = new Hono<{
  Bindings: Env
  Variables: Variables
}>()

export const oauthRoutes = new Hono<{
  Bindings: Env
  Variables: Variables
}>()

oauthRoutes.post("/device/code", rateLimitUnauthenticated, async (c) => {
  const body = await c.req.parseBody()
  const clientId = typeof body.client_id === "string" ? body.client_id : null
  const scope = typeof body.scope === "string" && body.scope.trim() ? body.scope : DEFAULT_SCOPE

  if (clientId !== CLI_CLIENT_ID) {
    return oauthError(c, "invalid_client", 401)
  }

  const { deviceCode, grant } = await createDeviceGrant(c, clientId, scope)

  const baseUri = verificationUri(c.env)
  return c.json({
    device_code: deviceCode,
    user_code: grant.userCode,
    verification_uri: baseUri,
    verification_uri_complete: `${baseUri}?code=${encodeURIComponent(grant.userCode)}`,
    expires_in: DEVICE_CODE_TTL_SECONDS,
    interval: grant.interval,
  })
})

oauthRoutes.post("/token", rateLimitUnauthenticated, async (c) => {
  const body = await c.req.parseBody()
  const grantType = typeof body.grant_type === "string" ? body.grant_type : null
  const clientId = typeof body.client_id === "string" ? body.client_id : null
  const deviceCode = typeof body.device_code === "string" ? body.device_code : null

  if (grantType !== "urn:ietf:params:oauth:grant-type:device_code") {
    return oauthError(c, "unsupported_grant_type")
  }

  if (clientId !== CLI_CLIENT_ID) {
    return oauthError(c, "invalid_client", 401)
  }

  if (!deviceCode) {
    return oauthError(c, "invalid_grant")
  }

  const grant = await getDeviceGrant(c, deviceCode)
  if (!grant || isExpired(grant)) {
    return oauthError(c, "expired_token")
  }

  if (grant.clientId !== clientId) {
    return oauthError(c, "invalid_grant")
  }

  if (grant.status === "consumed") {
    return oauthError(c, "invalid_grant")
  }

  const now = Date.now()
  const pollState = await getDevicePollState(c, deviceCode)
  const pollInterval = pollState?.interval ?? grant.interval
  const lastPolledAt = pollState?.lastPolledAt ?? grant.lastPolledAt

  if (lastPolledAt && now - lastPolledAt < pollInterval * 1000) {
    await saveDevicePollState(c, deviceCode, grant.expiresAt, {
      interval: pollInterval + DEVICE_POLL_INTERVAL_SECONDS,
      lastPolledAt: now,
    })
    return oauthError(c, "slow_down")
  }

  if (grant.status === "pending") {
    await saveDevicePollState(c, deviceCode, grant.expiresAt, {
      interval: pollInterval,
      lastPolledAt: now,
    })
    return oauthError(c, "authorization_pending")
  }

  if (grant.status === "denied") {
    return oauthError(c, "access_denied")
  }

  if (!grant.approvedByUserId) {
    return oauthError(c, "invalid_grant")
  }

  // Generate token at poll-time so plaintext never sits in KV
  const accessToken = await issueApiToken(c, grant.approvedByUserId, grant.scope)
  grant.status = "consumed"
  await Promise.all([
    saveDeviceGrant(c, deviceCode, grant),
    c.env.ENTIRE_CACHE.delete(devicePollStateKey(deviceCode)),
  ])

  return c.json({
    access_token: accessToken,
    token_type: "Bearer",
    expires_in: API_TOKEN_TTL_SECONDS,
    scope: grant.scope,
  })
})

// --- Authenticated endpoints ---

// POST /auth/decision — browser approves or denies the device code
cliAuthRoutes.post("/auth/decision", requireAuth, rateLimitAuthenticated, async (c) => {
  const body = await c.req.json<{ userCode?: string; decision?: "approve" | "deny" }>()
  return handleDecision(c, body.userCode, body.decision)
})

// GET /auth/tokens — list user's API tokens
cliAuthRoutes.get("/auth/tokens", requireAuth, async (c) => {
  const userId = c.get("userId")
  const db = getDb(c.env)
  const tokens = await db.apiTokens.listForUser(userId)
  return c.json({ tokens })
})

// DELETE /auth/tokens/:id — revoke a token
cliAuthRoutes.delete("/auth/tokens/:id", requireAuth, async (c) => {
  const userId = c.get("userId")
  const tokenId = c.req.param("id")
  if (!tokenId) {
    return c.json({ error: "Token not found" }, 404)
  }
  const db = getDb(c.env)
  const deleted = await nullIfInvalidUuid(db.apiTokens.deleteById(tokenId, userId))

  if (!deleted) {
    return c.json({ error: "Token not found" }, 404)
  }

  return c.json({ success: true })
})

