async function checkRepoAccess(
  db: Db,
  repoFullName: string,
  userId: string,
  options?: { requireRepo?: false },
): Promise<Repo | null | Response>
async function checkRepoAccess(
  db: Db,
  repoFullName: string,
  userId: string,
  options: { requireRepo?: boolean } = {},
): Promise<Repo | null | Response> {
  const result = await db.repos.getByFullNameWithAccess(repoFullName, userId)

  if (result.status === "found") {
    return result.repo
  }

  if (result.status === "not_found") {
    if (options.requireRepo) {
      return new Response(JSON.stringify({ error: "Repository not found" }), {
        status: 404,
        headers: { "Content-Type": "application/json" },
      })
    }
    return null
  }

  // status === "no_access"
  const publicRepo = await db.repos.getPublicByFullName(repoFullName)
  if (publicRepo) return publicRepo

  return new Response(JSON.stringify({ error: "Repository not found" }), {
    status: 404,
    headers: { "Content-Type": "application/json" },
  })
}

function trailRowToMetadata(row: TrailRow): TrailMetadata {
  const reviewers = Array.isArray(row.reviewers)
    ? (row.reviewers as unknown as TrailReviewer[])
    : []
  return {
    trail_id: row.trail_id,
    branch: row.branch,
    base: row.base,
    title: row.title,
    body: row.body ?? "",
    status: row.status,
    author: row.author,
    assignees: row.assignees,
    labels: row.labels,
    created_at: row.created_at,
    updated_at: row.updated_at,
    merged_at: row.merged_at,
    priority: (row.priority ?? "none") as TrailPriority,
    type: row.type as TrailType | undefined,
    reviewers,
    merge_base_sha: row.merge_base_sha,
    head_sha: row.head_sha,
  }
}

function trailRowToDiscussion(row: TrailRow): TrailDiscussion {
  const disc = row.discussion as unknown
  if (disc && typeof disc === "object" && "comments" in (disc as Record<string, unknown>)) {
    return disc as TrailDiscussion
  }
  return { comments: [] }
}

function trailRowToReviews(row: TrailRow): TrailReviews {
  const rev = row.reviews as unknown
  if (rev && typeof rev === "object" && "reviews" in (rev as Record<string, unknown>)) {
    return rev as TrailReviews
  }
  return { reviews: [] }

