branchesAfterAll := env.ListBranchesWithPrefix("entire/")
for _, b := range branchesAfterAll {
	if b != paths.MetadataBranchName && b != paths.TrailsBranchName {
		t.Errorf("Unexpected shadow branch after all files committed: %s", b)
