 15→// initTestRepo creates a test git repository with an initial commit.
 16→func initTestRepo(t *testing.T) *git.Repository {
 17→	t.Helper()
 18→
 19→	dir := t.TempDir()
 20→
 21→	ctx := context.Background()
 22→	cmds := [][]string{
 23→		{"git", "init", dir},
 24→		{"git", "-C", dir, "config", "user.name", "Test"},
 25→		{"git", "-C", dir, "config", "user.email", "test@test.com"},
 26→		{"git", "-C", dir, "config", "commit.gpgsign", "false"},
 27→	}
 28→	for _, args := range cmds {
 29→		cmd := exec.CommandContext(ctx, args[0], args[1:]...)
 30→		if out, err := cmd.CombinedOutput(); err != nil {
 31→			t.Fatalf("command %v failed: %v\n%s", args, err, out)
 32→		}
 33→	}
 34→
 35→	// Create a file and commit
 36→	if err := os.WriteFile(filepath.Join(dir, "README.md"), []byte("# Test"), 0o644); err != nil {
 37→		t.Fatalf("failed to write file: %v", err)
 38→	}
 39→	commitCmds := [][]string{
 40→		{"git", "-C", dir, "add", "."},
 41→		{"git", "-C", dir, "commit", "-m", "Initial commit"},
 42→	}
 43→	for _, args := range commitCmds {
 44→		cmd := exec.CommandContext(ctx, args[0], args[1:]...)
 45→		if out, err := cmd.CombinedOutput(); err != nil {
 46→			t.Fatalf("command %v failed: %v\n%s", args, err, out)
 47→		}
 48→	}
 49→
 50→	repo, err := git.PlainOpen(dir)
 51→	if err != nil {
 52→		t.Fatalf("failed to open repo: %v", err)
 53→	}
 54→	return repo
 55→}
