func runTrailShow(ctx context.Context, w io.Writer) error {
	branch, err := GetCurrentBranch(ctx)
	if err != nil {
		return runTrailListAll(ctx, w, "", false, false)
	}

	client, err := NewAuthenticatedAPIClient()
	if err != nil {
